"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81383"],{83244(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.passo_do_lancamento_invalido","status":422,"titulo":"O passo do lan\xe7amento, quando informado, deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.passo_do_lancamento_invalido","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["Uma das etapas do corpo do pedido informou `passoDoLancamento` igual a zero ou negativo.\\nO passo \xe9 o intervalo entre duas notas que o avaliador pode digitar; com passo zero\\nn\xe3o existe a nota seguinte, e com passo negativo a escala andaria para tr\xe1s.","O campo \xe9 opcional e nunca \xe9 obrigat\xf3rio. A recusa vale s\xf3 para o valor declarado e\\ncontradit\xf3rio, e chega no array `errors[]`, no campo `passoDoLancamento` da etapa,\\njunto das demais viola\xe7\xf5es da mesma defini\xe7\xe3o de etapas."],"comoResolver":["Informe um decimal positivo de at\xe9 4 casas (0,01; 0,25; 0,5; 1) que divida a nota\\nm\xe1xima da etapa. Se a nota m\xe1xima ainda n\xe3o foi decidida, omita os dois campos: a\\netapa em rascunho fica sem escala, e a escala s\xf3 \xe9 cobrada na publica\xe7\xe3o.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);